/** Every known setting, in ascending key order. */
export const SETTINGS = [
  { key: 'log.file', type: 'string', default: '' },
  { key: 'log.level', type: 'enum', members: ['debug', 'info', 'warn', 'error'], default: 'info' },
  { key: 'log.rotate', type: 'boolean', default: 'true' },
  { key: 'retry.attempts', type: 'integer', default: '3' },
  { key: 'retry.backoff', type: 'duration', default: '250ms' },
  { key: 'server.host', type: 'string', default: 'localhost' },
  { key: 'server.port', type: 'integer', default: '8080' },
  { key: 'server.timeout', type: 'duration', default: '30s' },
  { key: 'server.tls', type: 'boolean', default: 'false' },
  { key: 'tags', type: 'list', default: '' },
]

const BY_KEY = new Map(SETTINGS.map(declared => [declared.key, declared]))

/**
 * The setting one key names, or undefined when the schema does not know it.
 * @param {string} key - the dotted setting key.
 * @returns {{key: string, type: string, members?: string[], default: string} | undefined} the setting.
 */
export function setting(key) {
  return BY_KEY.get(key)
}

/**
 * The environment variable name a setting key travels under: `CONF_` followed by the key
 * uppercased with every `.` replaced by `_`.
 * @param {string} key - the dotted setting key.
 * @returns {string} the environment variable name.
 */
export function envName(key) {
  return `CONF_${key.toUpperCase().replace(/\./gu, '_')}`
}

const BY_ENV_NAME = new Map(SETTINGS.map(declared => [envName(declared.key), declared.key]))

/**
 * The setting key one environment variable name names, or undefined when it names none.
 * @param {string} name - the environment variable name, as written.
 * @returns {string | undefined} the dotted setting key.
 */
export function keyForEnvName(name) {
  return BY_ENV_NAME.get(name)
}

/**
 * The first schema key, in the order `values` was written, that the schema does not know.
 * @param {Map<string, {text: string, line: number, column: number}>} values - a layer's parsed values.
 * @returns {{key: string, entry: {text: string, line: number, column: number}} | undefined} the offender, if any.
 */
export function firstUnknownKey(values) {
  for (const [key, entry] of values) {
    if (setting(key) === undefined) return { key, entry }
  }
  return undefined
}

const DURATION_UNIT_MS = { ms: 1n, s: 1000n, m: 60000n, h: 3600000n }

/**
 * Coerce one raw value to the text its declared type renders as.
 * @param {string} key - the dotted setting key, for the message a failure words.
 * @param {{type: string, members?: string[]}} declared - the setting's declared type.
 * @param {string} text - the raw text a layer wrote, or the schema default.
 * @returns {string} the rendered text.
 * @throws {Error} worded `<key> is not ...` or `<key> has an empty item: ...` when `text` does not fit.
 */
export function coerce(key, declared, text) {
  switch (declared.type) {
    case 'string':
      return text
    case 'integer':
      if (!/^-?(?:0|[1-9]\d*)$/u.test(text)) throw new Error(`${key} is not an integer: ${text}`)
      return text
    case 'boolean':
      if (text !== 'true' && text !== 'false') throw new Error(`${key} is not a boolean: ${text}`)
      return text
    case 'enum':
      if (!declared.members.includes(text)) {
        throw new Error(`${key} is not one of ${declared.members.join('|')}: ${text}`)
      }
      return text
    case 'duration': {
      const match = /^(\d+)(ms|s|m|h)$/u.exec(text)
      if (!match) throw new Error(`${key} is not a duration: ${text}`)
      return (BigInt(match[1]) * DURATION_UNIT_MS[match[2]]).toString()
    }
    case 'list': {
      if (text === '') return ''
      const items = text.split(',').map(item => item.trim())
      if (items.some(item => item === '')) throw new Error(`${key} has an empty item: ${text}`)
      const seen = new Set()
      const kept = []
      for (const item of items) {
        if (!seen.has(item)) {
          seen.add(item)
          kept.push(item)
        }
