/** The command: `dump <file>`, `get <file> <key>`, `load <base> <site>` and `origin <base> <site>`. */

import { existsSync, readFileSync } from 'node:fs'
import { IniError, parse as parseIni } from './ini.js'
import { EnvError, merge, parseEnv } from './layer.js'
import { SETTINGS, coerce, firstUnknownKey, setting } from './schema.js'

const USAGE = 'usage: cli.js dump <file>|get <file> <key>|load <base> <site>|origin <base> <site>'

/** Report one failure the way the specification words it, and stop. */
function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

/** One INI layer, refused at its own position when the grammar rejects it. */
function iniLayer(name, path) {
  if (!existsSync(path)) fail(`cannot read ${path}`)
  try {
    return { name, source: path, values: parseIni(readFileSync(path, 'utf8')) }
  } catch (error) {
    if (!(error instanceof IniError)) throw error
    return fail(`${path}:${error.line}:${error.column}: ${error.message}`)
  }
}

/** An INI layer, additionally refused when it sets a key the schema does not know. */
function checkedIniLayer(name, path) {
  const layer = iniLayer(name, path)
  const offender = firstUnknownKey(layer.values)
  if (offender !== undefined) {
    return fail(`${path}:${offender.entry.line}:${offender.entry.column}: unknown setting ${offender.key}`)
  }
  return layer
}

/** The environment layer read from standard input, refused at its own position. */
function envLayer() {
  const text = readFileSync(0, 'utf8')
  try {
    return { name: 'env', source: '<stdin>', values: parseEnv(text) }
  } catch (error) {
    if (!(error instanceof EnvError)) throw error
    return fail(`<stdin>:${error.line}:${error.column}: ${error.message}`)
  }
}

const argv = process.argv.slice(2)
const mode = argv[0]
const arity = { dump: 2, get: 3, load: 3, origin: 3 }
if (argv.length !== arity[mode]) fail(USAGE)

const out = []

if (mode === 'dump' || mode === 'get') {
  const merged = merge([iniLayer('file', argv[1])])
  const raw = key => (merged.has(key) ? merged.get(key).text : setting(key).default)
  if (mode === 'dump') {
    for (const declared of SETTINGS) out.push(`${declared.key}=${raw(declared.key)}`)
  } else {
    if (setting(argv[2]) === undefined) fail(`unknown setting ${argv[2]}`)
    out.push(raw(argv[2]))
  }
} else {
  const base = checkedIniLayer('base', argv[1])
  const site = checkedIniLayer('site', argv[2])
  const env = envLayer()
  const merged = merge([base, site, env])

  if (mode === 'origin') {
    for (const declared of SETTINGS) {
      const entry = merged.get(declared.key)
      out.push(`${declared.key} ${entry === undefined ? 'default' : entry.layer}`)
    }
  } else {
    for (const declared of SETTINGS) {
      const entry = merged.get(declared.key)
      const text = entry === undefined ? declared.default : entry.text
      try {
        out.push(`${declared.key}=${coerce(declared.key, declared, text)}`)
      } catch (error) {
        if (entry === undefined) throw error
        fail(`${entry.source}:${entry.line}:${entry.column}: ${error.message}`)
      }
    }
  }
}

process.stdout.write(out.map(line => `${line}\n`).join(''))
"}

