const out = []

if (mode === 'dump' || mode === 'get') {
  const merged = merge([iniLayer('file', argv[1])])
  const raw = key => (merged.has(key) ? merged.get(key).text : setting(key).default)
  if (mode === 'dump') {
    for (const declared of SETTINGS) out.push(`${declared.key}=${raw(declared.key)}`)
  } else {
    if (setting(argv[2]) === undefined) fail(`unknown setting ${argv[2]}`)
    out.push(raw(argv[2]))
  }
} else {
  const base = checkedIniLayer('base', argv[1])
  const site = checkedIniLayer('site', argv[2])
  const env = envLayer()
  const merged = merge([base, site, env])

  if (mode === 'origin') {
    for (const declared of SETTINGS) {
      const entry = merged.get(declared.key)
      out.push(`${declared.key} ${entry === undefined ? 'default' : entry.layer}`)
    }
  } else {
    for (const declared of SETTINGS) {
      const entry = merged.get(declared.key)
      const text = entry === undefined ? declared.default : entry.text
      try {
        out.push(`${declared.key}=${coerce(declared.key, declared, text)}`)
      } catch (error) {
        if (entry === undefined) throw error
        fail(`${entry.source}:${entry.line}:${entry.column}: ${error.message}`)
      }
    }
  }
}

process.stdout.write(out.map(line => `${line}\n`).join(''))
